-- 3. Historias individuales, fichas y datos médicos simulados.
-- Valores permitidos para vacunas: Al día / Incompletas / Sin vacunas.
-- Para esterilización: Sí / No. 
INSERT INTO mascotas
(nombre, id_especie, raza, edad, tamano, descripcion, fotografia, ubicacion,
 estado, id_usuario, sexo, vacunas, esterilizada)
VALUES
    ('Milo', 1, 'Mestizo', '2 años', 'Mediano', 'Milo pasó sus primeros meses acompañando a una familia que, por un cambio de vivienda, ya no pudo cuidarlo. Desde entonces vive en un hogar temporal donde descubrió que le encanta perseguir pelotas y salir a caminar por senderos tranquilos. Es curioso, juguetón y busca estar cerca de las personas cuando descansan. Necesita una familia paciente que disfrute compartir actividades y lo haga sentir seguro en su nuevo hogar.', 'img/mascotas/Perros/Milo/milo-1.jpg', 'Alajuela', 'Disponible', 1, 'Macho', 'Al día', 'Sí'),
    ('Canela', 1, 'Mestizo', '8 meses', 'Pequeño', 'Canela apareció cerca de un pequeño mercado y una vecina decidió darle refugio mientras encontraba a sus responsables. Como nadie la reclamó, comenzó su búsqueda de una familia definitiva. Es una cachorrita alegre que se emociona con los juguetes de tela, aprende rápidamente las rutinas y adora las siestas junto a alguien. Su nueva familia deberá continuar con su educación, sus vacunas pendientes y los cuidados propios de su edad.', 'img/mascotas/Perros/Canela/canela-1.jpg', 'Heredia', 'Disponible', 1, 'Hembra', 'Incompletas', 'No'),
    ('Max', 1, 'Mestizo', '4 meses', 'Grande', 'Max nació en una camada que fue acogida por una familia voluntaria. Aunque todavía es un cachorro, por su constitución se espera que necesite bastante espacio y ejercicio cuando crezca. Le gusta olfatear el jardín, jugar con mordedores y dormir después de descubrir algo nuevo. Se beneficiará de una familia que pueda dedicarle tiempo a su socialización, enseñarle con cariño y acompañarlo durante todas sus etapas de crecimiento.', 'img/mascotas/Perros/Max/max-1.jpg', 'Cartago', 'Disponible', 1, 'Macho', 'Incompletas', 'No'),
    ('Toby', 1, 'Salchicha', '5 años', 'Pequeño', 'Toby vivió durante años con una persona mayor y se acostumbró a las mañanas tranquilas, los paseos cortos y las tardes de compañía. Un cambio familiar hizo necesario buscarle un nuevo hogar. Es observador, afectuoso y suele recibir a sus cuidadores moviendo la cola con entusiasmo. Sueña con una casa donde respeten sus tiempos, cuiden sus pequeñas patas y lo incluyan en las actividades cotidianas sin exigirle esfuerzos excesivos.', 'img/mascotas/Perros/Toby/toby-1.jpg', 'Alajuela', 'Disponible', 1, 'Macho', 'Al día', 'Sí'),
    ('Bella', 1, 'Mestizo', '1 año', 'Mediano', 'Bella fue recibida por una familia temporal después de pasar varias semanas cerca de una zona rural. Al principio evitaba los ruidos fuertes, pero con una rutina estable comenzó a mostrar su carácter dulce y confiado. Disfruta jugar con cuerdas, tumbarse bajo la sombra y recibir caricias cuando ella se acerca. Busca una familia que le ofrezca paciencia durante la adaptación y le permita seguir descubriendo el mundo a su propio ritmo.', 'img/mascotas/Perros/Bella/Bella-1.jpg', 'Guanacaste', 'Disponible', 1, 'Hembra', 'Al día', 'Sí'),
    ('Bolt', 1, 'Husky siberiano', '3 años', 'Grande', 'Bolt llegó a un hogar temporal cuando sus anteriores responsables comprendieron que no podían cubrir sus necesidades de actividad. Es un perro enérgico, inteligente y muy curioso, al que le encantan los paseos largos y los juegos de búsqueda. Después de ejercitarse disfruta descansar cerca de su familia. Necesita personas comprometidas con sus rutinas, un espacio seguro y salidas en horarios frescos para cuidar su bienestar.', 'img/mascotas/Perros/Bolt/Bolt-1.jpg', 'Heredia', 'Disponible', 1, 'Macho', 'Al día', 'Sí'),
    ('Bruno', 1, 'Labrador retriever', '4 años', 'Grande', 'Bruno acompañaba a una familia que se mudó a un lugar donde no podía mantener a un perro grande. En su hogar temporal se ganó el cariño de todos porque siempre está dispuesto a traer una pelota y compartir una tarde en el patio. Es sociable, paciente y disfruta aprender pequeños juegos de obediencia. Actualmente una familia está conociéndolo como parte del proceso de adopción, por lo que su solicitud permanece en revisión.', 'img/mascotas/Perros/Bruno/Bruno-1.jpg', 'Alajuela', 'En proceso', 1, 'Macho', 'Al día', 'Sí'),
    ('Chispa', 1, 'Chihuahua', '8 meses', 'Pequeño', 'Chispa recibió su nombre porque corre de un lado a otro apenas escucha el sonido de sus juguetes. Fue acogida por una pareja que ayudó a cuidar a varios cachorros de su comunidad. Es diminuta, vivaz y un poco tímida cuando conoce personas nuevas, pero pronto se acerca en busca de cariño. Necesita una familia que le enseñe hábitos con paciencia, continúe su calendario de vacunas y le ofrezca un lugar seguro donde descansar.', 'img/mascotas/Perros/Chispa/Chispa-1.jpg', 'Cartago', 'Disponible', 1, 'Hembra', 'Incompletas', 'No'),
    ('Coco', 1, 'Poodle', '2 años', 'Pequeño', 'Coco llegó al refugio temporal después de que su anterior familia cambiara de horario y dejara de poder acompañarlo. Conserva una gran curiosidad por las personas y se entusiasma cuando le hablan con voz suave. Le gusta aprender trucos sencillos, llevar su peluche favorito y esperar junto a la puerta cuando llega la hora del paseo. Busca un hogar con compañía frecuente y cuidados de cepillado para mantener cómodo su pelaje rizado.', 'img/mascotas/Perros/Coco/Coco-1.jpg', 'San José', 'Disponible', 1, 'Macho', 'Al día', 'Sí'),
    ('Duque', 1, 'Mestizo', '7 meses', 'Pequeño', 'Duque fue encontrado cerca de un camino rural y desde entonces ha estado creciendo al cuidado de una familia voluntaria. Tiene una forma muy particular de explorar: primero olfatea cada rincón y luego vuelve corriendo a buscar a su cuidador. Es divertido, despierto y le encantan los juegos de esconder premios. Necesita una familia dispuesta a continuar con sus vacunas, enseñarle rutinas y convertir sus primeras aventuras en recuerdos felices.', 'img/mascotas/Perros/Duque/Duque-1.jpg', 'Puntarenas', 'Disponible', 1, 'Macho', 'Incompletas', 'No'),
    ('Kira', 1, 'Mestizo', '3 años', 'Mediano', 'Kira fue rescatada después de pasar varios días sola cerca de una carretera. En su casa temporal aprendió a confiar nuevamente gracias a paseos tranquilos y horarios constantes. Hoy disfruta buscar juguetes, tomar el sol de la mañana y sentarse cerca de las personas que conoce. Puede mostrarse reservada en los primeros encuentros, por lo que necesita una familia comprensiva que respete su proceso de adaptación y celebre cada pequeño avance.', 'img/mascotas/Perros/Kira/Kira-1.jpg', 'Alajuela', 'Disponible', 1, 'Hembra', 'Al día', 'Sí'),
    ('Lola', 1, 'Schnauzer', '2 años', 'Pequeño', 'Lola siempre fue una compañera muy querida, pero una situación familiar inesperada hizo que necesitaran encontrarle un nuevo hogar. Tiene un carácter alegre y le encanta acompañar a las personas de una habitación a otra. Cuando ve su correa, comienza a dar pequeños saltos de emoción. Busca una familia que disfrute los paseos diarios, cuide regularmente su pelaje y le dé un lugar estable en el que pueda sentirse parte de todo.', 'img/mascotas/Perros/Lola/Lola-1.jpg', 'Heredia', 'Disponible', 1, 'Hembra', 'Al día', 'Sí'),
    ('Maxine', 1, 'Mestizo', '1 año', 'Mediano', 'Maxine fue acogida por una familia de la costa después de que apareciera sola cerca de un parque. Es una perrita activa que disfruta las caminatas, los juegos de olfato y las tardes de lluvia bajo techo. Al conocer a alguien nuevo prefiere observar primero, pero luego busca compañía con entusiasmo. Necesita un hogar con una rutina clara, paciencia y tiempo para seguir desarrollando su confianza sin perder su espíritu aventurero.', 'img/mascotas/Perros/Maxine/Maxine-1.jpg', 'Limón', 'Disponible', 1, 'Hembra', 'Al día', 'Sí'),
    ('Maya', 1, 'Beagle', '3 años', 'Mediano', 'Maya tiene una nariz curiosa y convierte cada paseo en una investigación de aromas. Llegó a una casa temporal cuando sus cuidadores anteriores dejaron de contar con tiempo para atenderla. Es amistosa y disfruta los juegos con premios escondidos, aunque necesita supervisión durante las caminatas porque los olores suelen distraerla. Una familia ya inició conversaciones para adoptarla; mientras termina la evaluación, su estado figura como en proceso.', 'img/mascotas/Perros/Maya/Maya-1.jpg', 'San José', 'En proceso', 1, 'Hembra', 'Al día', 'Sí'),
    ('Nina', 1, 'Cocker spaniel', '4 años', 'Mediano', 'Nina acompañó durante años a una familia que, por motivos de salud, tuvo que buscarle un hogar diferente. Es una perrita sensible que disfruta la música suave, las caricias detrás de las orejas y caminar sin prisa. En su casa temporal se adaptó bien a los horarios tranquilos y suele llevar su juguete favorito hasta donde descansan las personas. Busca una familia cariñosa que cuide su pelaje y respete su personalidad serena.', 'img/mascotas/Perros/Nina/Nina-1.jpg', 'Guanacaste', 'Disponible', 1, 'Hembra', 'Al día', 'Sí'),
    ('Oso', 1, 'Mestizo', '5 años', 'Grande', 'A Oso le pusieron ese nombre por su abundante pelaje negro y su apariencia imponente, aunque su actividad favorita es acostarse a los pies de alguien. Pasó una temporada al cuidado de un vecino después de que su familia se trasladara de provincia. Es calmado, disfruta las caminatas a la sombra y se anima cuando ve una pelota. Necesita una vivienda con espacio suficiente, cepillado frecuente y personas que aprecien su forma tranquila de dar cariño.', 'img/mascotas/Perros/Oso/Oso-1.jpg', 'Puntarenas', 'Disponible', 1, 'Macho', 'Al día', 'Sí'),
    ('Rocco', 1, 'Mestizo', '4 años', 'Grande', 'Rocco fue recogido por voluntarios luego de vivir un tiempo en un terreno sin un cuidador estable. Con constancia aprendió a esperar su comida, caminar con correa y relajarse en un entorno seguro. Es un perro fuerte, leal y entusiasta que necesita ejercicio y guía tranquila. Actualmente conoce a una familia interesada que está preparando su hogar para recibirlo, por eso su adopción permanece en proceso.', 'img/mascotas/Perros/Rocco/Rocco-1.jpg', 'Alajuela', 'En proceso', 1, 'Macho', 'Al día', 'Sí'),
    ('Rocky', 1, 'Pastor alemán', '7 años', 'Grande', 'Rocky dedicó varios años de su vida al trabajo junto a una unidad canina de seguridad. Ahora que está retirado, su mayor deseo es cambiar las jornadas intensas por paseos tranquilos, descanso y una familia que lo quiera por su compañía. Es atento, disciplinado y disfruta los juegos de olfato que le permiten mantenerse activo sin demasiada exigencia. Busca un hogar estable que respete su edad, sus rutinas y su merecido descanso.', 'img/mascotas/Perros/Rocky/Rocky-1.jpg', 'Cartago', 'Disponible', 1, 'Macho', 'Al día', 'Sí'),
    ('Simba', 1, 'Golden retriever', '2 años', 'Grande', 'Simba creció rodeado de personas y siempre ha disfrutado participar en las actividades familiares. Cuando sus cuidadores tuvieron que mudarse, una casa temporal lo recibió para buscarle una nueva oportunidad. Le encanta jugar con pelotas, caminar por el parque y descansar cerca de quien le presta atención. Necesita una familia activa que disfrute compartir tiempo con él, mantenga su educación y le ofrezca compañía diaria.', 'img/mascotas/Perros/Simba/Simba-1.jpg', 'Heredia', 'Disponible', 1, 'Macho', 'Al día', 'Sí'),
    ('Zeus', 1, 'Tipo pitbull', '1 año', 'Mediano', 'Zeus es un perro gris de mirada dulce que fue acogido por un rescatista después de quedar sin un hogar estable. Al principio se emocionaba tanto al jugar que necesitó aprender a esperar turnos y responder a instrucciones sencillas. Hoy disfruta los juguetes resistentes, los paseos con correa y descansar junto a su cuidador. Busca una familia responsable que continúe su educación con paciencia, le dé ejercicio y lo valore por su carácter, no por su apariencia.', 'img/mascotas/Perros/Zeus/Zeus-1.jpg', 'Limón', 'Disponible', 1, 'Macho', 'Al día', 'No'),
    ('Luna', 2, 'No especificada', '1 año', 'Pequeño', 'Luna apareció en el patio de una vivienda buscando un lugar tranquilo para pasar la noche. La familia que la encontró la cuidó hasta que recuperó la confianza en las personas. Es observadora, cariñosa y disfruta subir a lugares altos desde donde pueda mirar lo que sucede a su alrededor. Le gustan las caricias suaves y los ratos de juego con una cuerda. Busca un hogar sereno con rincones seguros, ventanas protegidas y compañía respetuosa.', 'img/mascotas/Gatos/luna/luna-1.jpg', 'San José', 'Disponible', 1, 'Hembra', 'Al día', 'Sí'),
    ('Nala', 2, 'No especificada', '3 años', 'Pequeño', 'Nala vivió sus primeros años en un apartamento donde tenía su propio espacio junto a una ventana soleada. Cuando la familia cambió de residencia, una persona cercana se ofreció a cuidarla temporalmente. Es una gata independiente que demuestra cariño acercándose a descansar junto a quienes conoce. Le encantan las mantas tibias y los juguetes pequeños. Busca un hogar tranquilo que le permita explorar a su ritmo y conservar sus rutinas.', 'img/mascotas/Gatos/nala/nala-1.jpg', 'San José', 'Disponible', 1, 'Hembra', 'Al día', 'Sí'),
    ('Copito', 2, 'Mestizo', '10 meses', 'Pequeño', 'Copito fue encontrado dentro de una caja de cartón durante una mañana lluviosa y recibió atención de una familia voluntaria. Desde entonces ha crecido rodeado de juguetes, mantas y personas que celebran sus travesuras. Es curioso, juguetón y no pierde oportunidad de perseguir una pelota que ruede por el suelo. Necesita una familia que continúe con su calendario de vacunas, le ofrezca espacios de juego y lo mantenga seguro dentro de casa.', 'img/mascotas/Gatos/Copito/Copito-1.jpg', 'Heredia', 'Disponible', 1, 'Macho', 'Incompletas', 'No'),
    ('Félix', 2, 'Mestizo atigrado', '2 años', 'Mediano', 'Félix solía visitar la terraza de un pequeño negocio hasta que sus cuidadores decidieron buscarle un hogar definitivo. Con el tiempo mostró su personalidad aventurera: le fascinan los rascadores altos, observar insectos desde la ventana y descubrir escondites nuevos. Después de jugar busca un sitio cómodo para descansar cerca de las personas. Necesita un hogar con enriquecimiento ambiental, paciencia y espacios seguros donde pueda trepar.', 'img/mascotas/Gatos/Félix/Félix-1.jpg', 'San José', 'Disponible', 1, 'Macho', 'Al día', 'Sí'),
    ('Kiara', 2, 'Siamés', '8 meses', 'Pequeño', 'Kiara llegó a una casa temporal cuando todavía era muy pequeña y creció acompañada de una familia que le enseñó a confiar en las personas. Es expresiva y suele maullar suavemente cuando quiere comida o invita a jugar. Le encantan las varitas con plumas y dormir en lugares cálidos. Busca un hogar que pueda brindarle atención diaria, juegos para estimular su curiosidad y seguimiento de sus vacunas y cuidados propios de su edad.', 'img/mascotas/Gatos/Kiara/Kiara-1.jpg', 'Guanacaste', 'Disponible', 1, 'Hembra', 'Incompletas', 'No'),
    ('Mía', 2, 'Mestizo carey', '3 años', 'Pequeño', 'Mía fue acogida después de que su antigua familia tuviera que trasladarse fuera del país. En su hogar temporal demuestra una personalidad muy especial: le gusta observar desde lejos antes de acercarse, pero luego reclama caricias con pequeños ronroneos. Disfruta los rincones tranquilos, las camas suaves y las sesiones cortas de juego. Busca una familia que entienda su independencia y le ofrezca cariño sin invadir su espacio.', 'img/mascotas/Gatos/Mía/Mía-1.jpg', 'Alajuela', 'Disponible', 1, 'Hembra', 'Al día', 'Sí'),
    ('Oliver', 2, 'Mestizo', '2 años', 'Mediano', 'Oliver se ganó su nombre porque siempre parecía saludar a todos con un maullido al entrar a la habitación. Fue recibido por un cuidador temporal después de pasar varios días en un parque de la comunidad. Es un gato sociable que disfruta perseguir pelotitas, investigar bolsas de papel y dormir donde llegue el sol. Necesita una familia que le brinde atención, espacios seguros para jugar y un lugar cómodo donde pueda seguir saludando cada mañana.', 'img/mascotas/Gatos/Oliver/Oliver-1.jpg', 'Heredia', 'Disponible', 1, 'Macho', 'Al día', 'Sí'),
    ('Pelusa', 2, 'Mestizo de pelo largo', '4 años', 'Mediano', 'Pelusa vivió mucho tiempo con una señora que la cepillaba cada tarde mientras escuchaba la radio. Cuando ella ya no pudo cuidarla, una familia temporal decidió mantener esa costumbre para que se sintiera acompañada. Es una gata calmada que aprecia las voces suaves, las mantas y los espacios silenciosos. Una familia interesada ya inició el proceso de adopción y está preparando un rincón especial para ella, por lo que su estado permanece en proceso.', 'img/mascotas/Gatos/Pelusa/Pelusa-1.jpg', 'Cartago', 'En proceso', 1, 'Hembra', 'Al día', 'Sí'),
    ('Salem', 2, 'Mestizo', '1 año', 'Pequeño', 'Salem fue rescatado de un patio donde se refugiaba durante las tardes calurosas. A pesar de su apariencia misteriosa, es un gato alegre que se emociona cuando ve juguetes colgantes y cajas vacías. Le encanta perseguir sombras, observar el movimiento de las hojas y pedir caricias con pequeños empujones de cabeza. Busca una familia que disfrute sus ocurrencias y lo mantenga protegido dentro del hogar, donde pueda explorar con tranquilidad.', 'img/mascotas/Gatos/Salem/Salem-1.jpg', 'Puntarenas', 'Disponible', 1, 'Macho', 'Al día', 'Sí'),
    ('Trufa', 2, 'Mestizo calicó', '2 años', 'Pequeño', 'Trufa recibió su nombre por las pequeñas manchas de distintos colores que decoran su pelaje. Llegó a una casa temporal después de que vecinos la encontraran buscando comida cerca de una plaza. Es dulce y curiosa: suele acompañar a sus cuidadores mientras trabajan y luego se acomoda a descansar cerca de una ventana. Busca una familia que le ofrezca un ambiente estable, juguetes sencillos y un rincón seguro donde pueda sentirse parte del hogar.', 'img/mascotas/Gatos/Trufa/Trufa-1.jpg', 'Limón', 'Disponible', 1, 'Hembra', 'Al día', 'Sí');

-- 4. Consultas de comprobación
SELECT COUNT(*) AS total_mascotas FROM mascotas;
SELECT * FROM mascotas;
SELECT * FROM usuarios;
